/**
 * Post-quantum producer vectors (conformance/producer-pq-vectors.json, generated by conformance/gen-producer-pq.mjs): the
 * reference producers must reproduce every `expect` from the case `args` alone, and signing twice must give the same bytes.
 * The second check pins the deterministic ML-DSA / SLH-DSA default of the pinned @noble/post-quantum version: a version that
 * hedges by default would make every native byte comparison fail, so it must fail here first.
 */
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { describe, expect, it } from 'vitest';
import { delegate, mintRoot } from './capability';
import { signEscalationAnswer } from './escalation';
import { signRevocationEpoch } from './revocation';
import { signPCActnSuite, type PCActnBody } from './pcactn';
import { fnDsa1024Keygen, fnDsa512Keygen, isFnDsaBackendActive, mlDsa65Keygen, mlDsa87Keygen, signWithSuite, slhDsa128fKeygen, slhDsa256sKeygen, type SigAlg } from './pq';
import { b64u, utf8 } from './hash';

type Args = any; // eslint-disable-line @typescript-eslint/no-explicit-any
const doc = JSON.parse(readFileSync(join(__dirname, '..', 'conformance', 'producer-pq-vectors.json'), 'utf8')) as {
  ed_keys: Record<string, { seed: string; public: string }>;
  pq_keys: Record<string, { family: string; seed: string; public: string; sign_seed?: string }>;
  cases: Array<{ name: string; op: string; alg?: SigAlg; exact: string[]; args: Args; expect: Args }>;
};
const bytes = (s: string): Uint8Array => new Uint8Array(Buffer.from(s, 'base64url'));
const edSk = (name: string): Uint8Array => bytes(doc.ed_keys[name]!.seed);
const edPk = (name: string): string => doc.ed_keys[name]!.public;

const KEYGEN: Record<string, (seed: Uint8Array) => Args> = {
  'ml-dsa-65': mlDsa65Keygen,
  'ml-dsa-87': mlDsa87Keygen,
  'slh-dsa-sha2-128f': slhDsa128fKeygen,
  'slh-dsa-sha2-256s': slhDsa256sKeygen,
  'fn-dsa-512': fnDsa512Keygen,
  'fn-dsa-1024': fnDsa1024Keygen,
};
const SLOT: Record<string, string> = {
  'ml-dsa-65': 'mlDsa', 'ml-dsa-87': 'mlDsa87', 'slh-dsa-sha2-128f': 'slhDsa', 'slh-dsa-sha2-256s': 'slhDsa256s', 'fn-dsa-512': 'fnDsa512', 'fn-dsa-1024': 'fnDsa1024',
};
const keyCache = new Map<string, Args>();
/** `{ [slot]: material }` for a named PQ key (empty for null), ready to spread into suite options. */
function pqMaterial(name: string | null): Record<string, Args> {
  if (name === null) return {};
  const k = doc.pq_keys[name]!;
  let m = keyCache.get(name);
  if (m === undefined) {
    const kp = KEYGEN[k.family]!(bytes(k.seed));
    m = k.family.startsWith('fn-dsa') ? { ...kp, signSeed: bytes(k.sign_seed!) } : kp;
    keyCache.set(name, m);
  }
  return { [SLOT[k.family]!]: m };
}
const pqPublic = (name: string | null): string | undefined => (name === null ? undefined : doc.pq_keys[name]!.public);
const json = <T>(v: T): T => JSON.parse(JSON.stringify(v)) as T;

const run: Record<string, (a: Args) => unknown> = {
  pq_keygen: (a) => {
    const kp = KEYGEN[a.family]!(bytes(a.seed));
    return { public: b64u(kp.publicKey ?? kp.verifyingKey) };
  },
  suite_sign: (a) => signWithSuite(a.alg, { ...(a.ed ? { edSecret: edSk(a.ed) } : {}), ...pqMaterial(a.pq) }, utf8(a.message_utf8)),
  mint_root_suite: (a) =>
    mintRoot({ principalSecret: edSk(a.principal), principalPublic: edPk(a.principal), holder: edPk(a.holder), ...(a.holder_pq ? { holderPq: pqPublic(a.holder_pq) } : {}), caveats: a.caveats, suite: { alg: a.alg, ...pqMaterial(a.pq) } }),
  delegate_suite: (a) => delegate(a.parent, edPk(a.to_holder), a.added_caveats, edSk(a.signer), { alg: a.alg, ...pqMaterial(a.pq) }, pqPublic(a.holder_pq)),
  sign_pcactn_suite: (a) => ({ pcactn: signPCActnSuite(a.body as PCActnBody, { alg: a.alg, edLeafSecret: edSk(a.signer), ...pqMaterial(a.pq) }) }),
  sign_artifact_suite: (a) => {
    const suite = { alg: a.alg, ...pqMaterial(a.pq) };
    if (a.kind === 'escalation_answer') return signEscalationAnswer(a.body, edSk(a.signer), suite);
    if (a.kind === 'revocation_epoch') return signRevocationEpoch(edSk(a.signer), a.body, suite);
    throw new Error(`unknown artifact kind ${a.kind}`);
  },
};

describe('post-quantum producer vectors (fixed seeds, deterministic signing, exact outputs)', () => {
  it('the FN-DSA backend is loaded (else the FN-DSA cases cannot be reproduced)', () => {
    expect(isFnDsaBackendActive()).toBe(true);
  });
  it('every op is covered and every non-LESS suite appears', () => {
    for (const c of doc.cases) expect(run[c.op], c.op).toBeDefined();
    const algs = new Set(doc.cases.filter((c) => c.op === 'suite_sign').map((c) => c.alg));
    expect([...algs].sort()).toEqual([
      'ed25519', 'fn-dsa-1024', 'fn-dsa-512', 'hybrid-ed25519-ml-dsa-65', 'hybrid-ed25519-ml-dsa-87', 'hybrid-ed25519-slh-dsa-sha2-128f',
      'hybrid-ed25519-slh-dsa-sha2-256s', 'hybrid-nested-ed25519-ml-dsa-65', 'ml-dsa-65', 'ml-dsa-87', 'slh-dsa-sha2-128f', 'slh-dsa-sha2-256s',
    ]);
  });
  for (const c of doc.cases) {
    it(c.name, () => {
      expect(json(run[c.op]!(c.args))).toEqual(json(c.expect));
    }, 60_000);
  }
  it('ML-DSA and SLH-DSA signing is deterministic: the same key and message sign to the same bytes', () => {
    for (const alg of ['ml-dsa-65', 'ml-dsa-87', 'slh-dsa-sha2-128f'] as const) {
      const keys = pqMaterial(`agent/${alg}`);
      const a = signWithSuite(alg, keys, utf8('determinism'));
      const b = signWithSuite(alg, keys, utf8('determinism'));
      expect(a.sig, alg).toBe(b.sig);
    }
  });
});
